function expandExpected(wire) {
  const cache=new Map();
  const unpack=v=>{if(v===null||typeof v!=="object")return v;assert.deepEqual(Object.keys(v),["d"]);if(cache.has(v.d))return cache.get(v.d);const row=wire.table[v.d];assert.ok(row);const out=row[0]==="s"?row[1]:row[0]==="a"?row[1].map(unpack):Object.fromEntries(row[1].map(([k,x])=>[k,unpack(x)]));cache.set(v.d,out);return out;};
  return unpack(wire.root);
}
